# November 16, 2026: one first place in every US state the Atlas had none in, and in seven Canadian provinces.
# The point of this batch is to open each state: its outline, region and start city now exist (tools/states.py,
# tools/outlines.py), and each has one worked example to copy. Every place here is on land open to visitors or can be
# seen from a public way. Facts come from the linked sources only: Wikipedia articles read as raw text
# (tools/wiki_raw.py) and the managing agency's own page for access. Where a detail could not be found it is left out.
# Pins were looked at on Esri satellite (research/pincheck_states_*.jpg); each pin note says what that showed.
from data_b import N
from data_ma import W
